 counterparties:[{id:'p0',name:'ЧАСТНОЕ ЛИЦО',inn:'0000000000',kpp:'',form:'Физическое лицо',agreement:'Розничное обслуживание'},{id:'p1',name:'ООО «Транслогистика»',inn:'7701000001',kpp:'770101001',form:'Юридическое лицо',agreement:'Договор сервиса № 1'},{id:'p2',name:'ООО «СеверТранс»',inn:'7201000002',kpp:'720101001',form:'Юридическое лицо',agreement:'Договор сервиса № 2'},{id:'p3',name:'ИП Орлов Н. П.',inn:'720100000003',kpp:'',form:'Индивидуальный предприниматель',agreement:'Договор сервиса № 3'}],
 vehicles:[{id:'v1',name:'КАМАЗ 65115',vin:'XTC651150N1234567',plate:'А123АА72',brand:'КАМАЗ',model:'65115',spec:'ДВС КАМАЗ / КПП ZF',client:'ООО «Транслогистика»'},{id:'v2',name:'МАЗ 5440',vin:'Y3M544000N1234567',plate:'В456ВВ72',brand:'МАЗ',model:'5440',spec:'ДВС ЯМЗ / КПП ZF',client:'ООО «СеверТранс»'}],
 brand:[{id:'br1',name:'КАМАЗ'},{id:'br2',name:'МАЗ'},{id:'br3',name:'УРАЛ'},{id:'br4',name:'VOLVO'},{id:'br5',name:'Агрегат'}],
