function itemRows(type){return S.items[type].map((r,i)=>trow(['<input type="checkbox" data-item-check="'+type+'.'+i+'" '+(r.agreed?'checked':'')+'>',h(r.code||''),'<input class="entry" data-item-field="'+type+'.'+i+'.name" value="'+h(r.name||'')+'" '+dataHelp('Номенклатура/авторабота','Введите название вручную или выберите позицию из справочника.')+'>','<input type="number" min="0.1" step="0.1" class="entry" data-item-field="'+type+'.'+i+'.quantity" value="'+h(r.quantity||'')+'" '+dataHelp('Количество','Укажите количество единиц или услуг самостоятельно.')+'>','<input type="number" min="0" step="0.01" class="entry" data-item-field="'+type+'.'+i+'.price" value="'+h(r.price||'')+'" '+dataHelp('Цена','Укажите согласованную цену, если она известна.')+'>',h((Number(r.quantity||0)*Number(r.price||0)).toFixed(2))]));}
